parent_dir = 'data/apple_disease_classification/Train'
if os.path.exists(parent_dir):
    dirs = os.listdir(parent_dir)
    print(f"Subdirectories in Train: {dirs}")

    for subdir in dirs:
        subdir_path = os.path.join(parent_dir, subdir)
        if os.path.isdir(subdir_path):
            files = os.listdir(subdir_path)
            print(f"\n{subdir}: {len(files)} files")
            if files:
                sample_file = os.path.join(subdir_path, files[0])
                print(f"  Sample file: {files[0]}, size: {os.path.getsize(sample_file)} bytes")"}

